const statusMeta=(value:string)=>{const key=(value||'').toLocaleLowerCase('tr-TR');if(['new','yeni'].includes(key))return ['Yeni','new'];if(['review','inceleniyor','işlemde'].includes(key))return ['İnceleniyor','review'];if(['contacted','arandı'].includes(key))return ['Arandı','contacted'];if(['callback','aranacak'].includes(key))return ['Aranacak','callback'];if(['answered','cevap verildi'].includes(key))return ['Cevap verildi','answered'];if(['resolved','çözüldü'].includes(key))return ['Çözüldü','resolved'];if(['closed','kapatıldı'].includes(key))return ['Kapatıldı','closed'];if(['scheduled','servis planlandı','planlandı'].includes(key))return ['Servis planlandı','scheduled'];if(['parts','parça bekliyor'].includes(key))return ['Parça bekliyor','parts'];if(['completed','tamamlandı'].includes(key))return ['Tamamlandı','completed'];if(['cancelled','iptal'].includes(key))return ['İptal','cancelled'];if(['stokta'].includes(key))return ['Stokta','instock'];if(['sipariş üzerine'].includes(key))return ['Sipariş üzerine','order'];if(['bilgi alınız'].includes(key))return ['Bilgi alınız','info'];if(['yayında'].includes(key))return ['Yayında','published'];if(['gizli'].includes(key))return ['Gizli','hidden'];return [value||'Durum yok','neutral'];};
function StatusBadge({value}:{value:string}){const [label,tone]=statusMeta(value);return <span className={'status-badge status-'+tone}>{label}</span>;}
const purposeMeta=(value:string,service=false)=>{if(service)return ['Teknik servis','servis'];const key=(value||'').toLocaleLowerCase('tr-TR');if(key==='teklif')return ['Teklif','teklif'];if(key==='servis')return ['Teknik servis','servis'];if(key==='yedek')return ['Yedek parça','yedek'];if(key==='genel')return ['Genel destek','genel'];return ['Belirtilmedi','none'];};
